{"id":"cue-12-12360","group_id":"source-speech-v1:cue-12-12360","source_start_seconds":12.36,"source_end_seconds":13.28,"speaking_duration_seconds":0.92,"text":"仅仅一个撞击"}
{"id":"cue-13-13280","group_id":"source-speech-v1:cue-12-12360","source_start_seconds":13.28,"source_end_seconds":14.38,"speaking_duration_seconds":1.1,"text":"狮子就飞了出去"}
{"id":"cue-14-14380","group_id":"source-speech-v1:cue-12-12360","source_start_seconds":14.38,"source_end_seconds":15.12,"speaking_duration_seconds":0.74,"text":"在踩上几脚"}
{"id":"cue-15-15120","group_id":"source-speech-v1:cue-12-12360","source_start_seconds":15.12,"source_end_seconds":16.32,"speaking_duration_seconds":1.2,"text":"狮子飞死即残"}
